/// <summary>
/// Extension of form markupTrans
/// </summary>
[ExtensionOf(formStr(MarkupTrans))]
final class AVAMarkupTransFrm_Extension
{
}

Method.Source:
/// <summary>
/// extension of init method
/// </summary>
/// <param name = "_callerForm">FormRun</param>
public void init(FormRun _callerForm)
{
    next init(_callerForm);

    switch (callerTableId)
    {
        //case tableNum(AgreementLine):
        //case tableNum(PurchAgreementheader):
        //    markupTrans_ds.query().dataSourceTable(tableNum(MarkupTrans)).addRange(fieldNum(MarkupTrans, SourceDocumentLine)).value(SysQuery::valueNotEmptyString());
        //    break;


        case tableNum(AgreementLineHistory):
        case tableNum(PurchAgreementHeaderHistory):
        case tableNum(SalesAgreementHeaderHistory):
            this.mcrDisableForm();
            break;
    }

    markupAllowEdit.visible(markupAllowEdit.visible() || callerTableId == tableNum(PurchTable) || callerTableId == tableNum(PurchLine));
}

/// <summary>
/// enables or disables control MarkupTransAVACalcQty based on MarkupCategory value
/// </summary>
public void avaEnableCalcQty()
{
    if(MarkupTrans.MarkupCategory == MarkupCategory::AVAMTZ)
    {
        this.design().controlName(formControlStr(MarkupTrans, MarkupTrans_AVACalcQty)).enabled(true);
    }
    else
    {
        this.design().controlName(formControlStr(MarkupTrans, MarkupTrans_AVACalcQty)).enabled(false);
    }
}

/// <summary>
/// Extension of closed method
/// </summary>
/// <returns>boolean</returns>
public boolean closed()
{
    boolean ret = next closed();

    this.avaRefreshCallerUI();

    return ret;
}

/// <summary>
/// Researches and refreshes caller formDataSource and UI
/// </summary>
public void avaRefreshCallerUI()
{
    FormDataSource fds = FormDataUtil::getFormDataSource(this.args().record());

    if(fds)
    {
        switch(fds.table())
        {
            case tableNum(SalesLine):
            case tableNum(SalesTable):
                fds.research(true);
                fds.refresh();
                break;

            default:
                break;
        }
    }
}
